const student = "Sirosh Sasha";
const group = "ИИ-241";
const numbers = [10, 20, 30, 40, 50];

let total = 0;
for (let i = 0; i < numbers.length; i++) {
  total += numbers[i];
}

let status = "";
if (total > 100) {
  status = "Success: total exceeds threshold";
} else {
  status = "Pending: total is low";
}

const resultObj = {
  student: student,
  group: group,
  calculatedTotal: total,
  status: status,
  timestamp: new Date().toISOString()
};

return [
  {
    json: {
      payload: resultObj
    }
  }
];
